class Solution {
    public boolean validTree(int n, int[][] edges) {
        if (edges.length != n - 1) {
            return false;
        }

        List<List<Integer>> graph = new ArrayList<>();
        for (int node = 0; node < n; node++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        boolean[] seen = new boolean[n];
        Queue<Integer> queue = new ArrayDeque<>();
        queue.offer(0);
        seen[0] = true;
        int visited = 0;

        while (!queue.isEmpty()) {
            int node = queue.poll();
            visited++;
            for (int next : graph.get(node)) {
                if (!seen[next]) {
                    seen[next] = true;
                    queue.offer(next);
                }
            }
        }

        return visited == n;
    }
}

import java.util.*;

class Solution {
    public boolean validTree(int n, int[][] edges) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int node = 0; node < n; node++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        boolean[] visited = new boolean[n];
        if (hasCycle(0, -1, graph, visited)) {
            return false;
        }
        for (boolean wasVisited : visited) {
            if (!wasVisited) {
                return false;
            }
        }
        return true;
    }

    private boolean hasCycle(int node, int parent, List<List<Integer>> graph, boolean[] visited) {
        visited[node] = true;
        for (int next : graph.get(node)) {
            if (next == parent) {
                continue;
            }
            if (visited[next]) {
                return true;
            }
            if (hasCycle(next, node, graph, visited)) {
                return true;
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public boolean validTree(int n, int[][] edges) {
        if (edges.length != n - 1) {
            return false;
        }
        if (n == 1) {
            return true;
        }

        List<List<Integer>> graph = new ArrayList<>();
        int[] degree = new int[n];
        for (int node = 0; node < n; node++) {
            graph.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
            degree[edge[0]]++;
            degree[edge[1]]++;
        }

        Queue<Integer> leaves = new ArrayDeque<>();
        for (int node = 0; node < n; node++) {
            if (degree[node] == 1) {
                leaves.offer(node);
            }
        }

        int removed = 0;
        while (!leaves.isEmpty()) {
            int node = leaves.poll();
            removed++;
            for (int next : graph.get(node)) {
                degree[next]--;
                if (degree[next] == 1) {
                    leaves.offer(next);
                }
            }
        }
        return removed == n;
    }
}
